package local.dinerdash.prototype;

import android.app.Instrumentation;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import android.os.SystemClock;
import android.view.MotionEvent;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Synthetic save/result fixtures exercise installed Activity transitions; saves are restored. */
public final class AndroidProgressTest extends Instrumentation {
    private int checks;
    private String regression="";
    private MainActivity activity;
    private MenuView menu;
    private void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    private Object field(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
    private void capture(String name)throws Exception{waitForIdleSync();Thread.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir("review"),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    private void choose(int slot){menu.show("title_screen");activity.menuAction("login_button");activity.menuAction("box_"+(slot+1));activity.menuAction("play");}
    private void pressMenu(String action)throws Exception{menu.draw(new Canvas(Bitmap.createBitmap(menu.getWidth(),menu.getHeight(),Bitmap.Config.ARGB_8888)));Field f=MenuView.class.getDeclaredField("buttons");f.setAccessible(true);RectF b=((Map<String,RectF>)f.get(menu)).get(action);check(b!=null,"The result must expose its "+action+" touch region");float s=Math.min(menu.getWidth()/800f,menu.getHeight()/600f),x=(menu.getWidth()-800*s)/2+b.centerX()*s,y=(menu.getHeight()-600*s)/2+b.centerY()*s;long now=SystemClock.uptimeMillis();for(int type:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(now,now,type,x,y,0);menu.onTouchEvent(e);e.recycle();}}
    private void resultFixture(int level,boolean won)throws Exception{resultFixture(level,won,-1);}
    private void resultFixture(int level,boolean won,int score)throws Exception{GameEngine g=new GameEngine(LevelData.get(level),1);g.stars=4;g.totalStars=5;g.score=score<0?(won?g.goal:0):score;GameEngine.Party p=new GameEngine.Party(0,new GameEngine.Arrival(0,new int[]{0,0},true));p.cookingUntil=10000;g.parties.add(p);Field f=MainActivity.class.getDeclaredField("game");f.setAccessible(true);f.set(activity,g);GameView board=(GameView)field("board");board.setGame(g);board.setVisibility(android.view.View.VISIBLE);board.layout(0,0,menu.getWidth(),menu.getHeight());Bitmap frame=Bitmap.createBitmap(board.getWidth(),board.getHeight(),Bitmap.Config.ARGB_8888);for(long time:new long[]{100,500,10000,10750}){g.time=time;board.draw(new Canvas(frame));}frame.recycle();g.ended=true;g.won=won;activity.finished(g);}
    private void regressions(String only)throws Exception{for(String name:new String[]{"shop","final","cancel","duplicate"}){if(!only.isEmpty()&&!only.equals(name))continue;Throwable[] failure={null};runOnMainSync(()->{try{
        choose(8);SharedPreferences settings=(SharedPreferences)field("saved"),progress=(SharedPreferences)field("progress");
        if(name.equals("shop")){GameEngine g=new GameEngine(LevelData.endless(1,1),1);g.tableUpgrade=g.level.tableUpgrades.size();for(String type:new String[]{"podium","maitred","drinks","shoes","oven","stereo"}){int count=0;while(LevelData.upgrade(type,count)!=null)count++;g.upgrades.put(type,count);}g.availableUpgrades=1;Field f=MainActivity.class.getDeclaredField("game");f.setAccessible(true);f.set(activity,g);((GameView)field("board")).setGame(g);activity.shop();check(menu.upgradeChoices.isEmpty(),"Exhausted inventory must offer no more upgrades");Method visible=MenuView.class.getDeclaredMethod("visible",String.class,String.class);visible.setAccessible(true);check((Boolean)visible.invoke(menu,"endless_shop","continue_button"),"Unspent credit with no upgrades left must still expose Continue");pressMenu("continue_button");check(field("game")==g&&!g.paused&&menu.getVisibility()==android.view.View.GONE,"Exhausted upgrades with unspent credit must resume the same endless run");
            g=new GameEngine(LevelData.endless(1,1),1);g.availableUpgrades=1;int tables=g.level.tables.size();f.set(activity,g);((GameView)field("board")).setGame(g);activity.shop();check(menu.upgradeChoices.size()==3&&menu.upgradeChoices.get(0).type.equals("table"),"A stocked shop must offer its original table choice and two powerups");pressMenu("item_1");check(g.availableUpgrades==0&&g.tableUpgrade==1&&g.level.tables.size()==tables+1,"One upgrade tap must purchase exactly one table and consume exactly one credit");pressMenu("continue_button");check(field("game")==g&&!g.paused&&menu.getVisibility()==android.view.View.GONE,"Continue after a purchase must resume the same upgraded endless run");}
        if(name.equals("final")){int checkpoint=90000,expert=LevelData.get(50).expert;progress.edit().putInt("current",50).putInt("unlocked",50).putInt("lives",4).putInt("totalStars",5).putInt("totalScore",checkpoint).remove("best50").commit();choose(8);resultFixture(50,true,expert);check(progress.getInt("totalScore",-1)==checkpoint,"Finishing shift 50 must keep the pre-final resume score instead of adding it again on replay");check(progress.getInt("best50",0)==expert&&menu.totalScore==checkpoint+expert,"The final expert record and completed total must still be submitted");activity.menuAction("quit_button");activity.menuAction("menubutton");activity.menuAction("career_button");pressMenu("play_button");check(((GameEngine)field("game")).level.number==50,"The original final-shift checkpoint must remain replayable");resultFixture(50,true,expert);check(progress.getInt("totalScore",-1)==checkpoint&&menu.totalScore==checkpoint+expert&&menu.scoreValues[0][0]==checkpoint+expert,"Replaying the final checkpoint must not inflate run totals or leaderboard scores");}
        if(name.equals("cancel")){activity.menuAction("login_button");activity.menuAction("box_10");activity.menuAction("cancel");check(menu.profile.equals("QA Alice")&&menu.profileSlot==8&&settings.getInt("profileSlot",-1)==8,"Cancelling a different profile selection must restore the active player");activity.menuAction("login_button");activity.menuAction("box_8");((android.widget.EditText)field("profileInput")).setText("Discard Me");activity.menuAction("cancel");check(settings.getString("profile7","").isEmpty()&&menu.profile.equals("QA Alice")&&settings.getInt("profileSlot",-1)==8,"Cancel must discard a typed new player without creating or selecting it");check(field("profileInput")==null,"Cancel must remove the temporary player-name editor");}
        if(name.equals("duplicate")){for(String candidate:new String[]{" QA   Alice ","qa alice"}){menu.show("title_screen");activity.menuAction("login_button");activity.menuAction("box_8");((android.widget.EditText)field("profileInput")).setText(candidate);activity.menuAction("play");check(settings.getString("profile7","").isEmpty()&&settings.getInt("profileSlot",-1)==8&&menu.screen.equals("login"),"Names already taken, including normalized spacing and case, must not create or select another profile");check(field("profileInput")!=null,"A duplicate name must remain editable rather than silently switching players");activity.menuAction("cancel");}activity.menuAction("login_button");activity.menuAction("box_8");((android.widget.EditText)field("profileInput")).setText("  New   Player ");activity.menuAction("play");check(settings.getString("profile7","").equals("New Player")&&menu.profile.equals("New Player"),"A unique name must retain its display case while normalizing word spacing");}
        }catch(Throwable error){menu.show("title_screen");failure[0]=error;}});if(failure[0]!=null)throw new AssertionError(name+" regression: "+failure[0],failure[0]);}}
    private void restore(SharedPreferences p,Map<String,?> data){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> v:data.entrySet()){Object x=v.getValue();if(x instanceof Integer)e.putInt(v.getKey(),(Integer)x);else if(x instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)x);else if(x instanceof String)e.putString(v.getKey(),(String)x);else throw new IllegalStateException("Unexpected save type "+x);}e.commit();}
    @Override public void onCreate(Bundle args){super.onCreate(args);regression=args.getString("regression","");start();}
    @Override public void onStart(){Bundle result=new Bundle();List<SharedPreferences> stores=new ArrayList<>();List<Map<String,?>> backups=new ArrayList<>();try{
        Context c=getTargetContext();stores.add(c.getSharedPreferences("career",0));for(int i=0;i<10;i++)stores.add(c.getSharedPreferences("career_profile_"+i,0));for(SharedPreferences p:stores)backups.add(new HashMap<>(p.getAll()));
        SharedPreferences settings=stores.get(0),alice=stores.get(9),bob=stores.get(10);alice.edit().clear().commit();bob.edit().clear().commit();settings.edit().clear().putString("profile8","QA Alice").putString("profile9","QA Bob").putInt("profileSlot",8).putInt("current",3).putInt("unlocked",3).putInt("lives",1).putInt("totalScore",1500).putInt("best1",LevelData.get(1).goal).putInt("best2",LevelData.get(2).expert).commit();
        activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));menu=(MenuView)field("menus");
        waitForIdleSync();Thread.sleep(300);
        if(regression.isEmpty()){
        check(alice.getInt("current",0)==3&&alice.getInt("totalScore",0)==1500,"Updating must retain the selected player's old career save");
        check(!menu.experts[0]&&menu.experts[1],"A normal win must stay a plain dot; only reaching the expert threshold earns a star");
        Method marker=MenuView.class.getDeclaredMethod("normalMember",String.class,String.class,org.json.JSONObject.class);marker.setAccessible(true);check(marker.invoke(menu,"career_setup","lvlbutton_1_1",new org.json.JSONObject()).equals("leveldot_normal")&&marker.invoke(menu,"career_setup","lvlbutton_1_2",new org.json.JSONObject()).equals("leveldot_star_normal"),"The drawn career markers must distinguish ordinary completion from earned expert stars");
        runOnMainSync(()->{menu.show("career_setup");});capture("phone-career-normal-expert");
        runOnMainSync(()->{choose(9);});check(menu.current==1&&menu.unlocked==1&&!menu.experts[1],"A different player must start with independent progress and expert records");runOnMainSync(()->{menu.show("career_setup");});capture("phone-profile-independent");
        runOnMainSync(()->{choose(8);});check(menu.current==3&&menu.experts[1],"Switching back must reload that player's retained career");
        for(int level:new int[]{1,10,49}){runOnMainSync(()->{try{resultFixture(level,true);pressMenu("continue_button");GameEngine next=(GameEngine)field("game");check(menu.screen.equals("startlevel")&&next.level.number==level+1,"Continue must open the next shift after a cooked winning result, including restaurant transitions");check(next.totalStars==5&&next.stars==(level==10?LevelData.get(11).stars:4),"Continue must retain earned star capacity separately from remaining lives, including restaurant changes");((GameView)field("board")).draw(new Canvas(Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888)));pressMenu("okbutton");check(!next.paused,"The next shift must become playable after acknowledging its introduction");}catch(Exception e){throw new RuntimeException(e);}});if(level==1)capture("phone-continue-after-cooking");}
        runOnMainSync(()->{try{resultFixture(5,false);pressMenu("tryagain_button");check(menu.screen.equals("startlevel")&&((GameEngine)field("game")).level.number==5,"Retry must reset the same chef timeline without changing shifts");}catch(Exception e){throw new RuntimeException(e);}});
        GameEngine failed=new GameEngine(LevelData.get(3));failed.stars=1;failed.ended=true;failed.won=false;
        runOnMainSync(()->{try{Field f=MainActivity.class.getDeclaredField("game");f.setAccessible(true);f.set(activity,failed);((GameView)field("board")).setGame(failed);((GameView)field("board")).setVisibility(android.view.View.VISIBLE);activity.finished(failed);}catch(Exception e){throw new RuntimeException(e);}});
        check(alice.getInt("lives",-1)==0&&menu.gameOver,"Failing the final life must reach zero and end the run, without clamping back to one");Method visible=MenuView.class.getDeclaredMethod("visible",String.class,String.class);visible.setAccessible(true);check((Boolean)visible.invoke(menu,"endlevel_window","quit_button")&&!(Boolean)visible.invoke(menu,"endlevel_window","tryagain_button"),"The final-life result must draw Quit and hide Retry so a finished run cannot silently restart");capture("phone-final-life-result");
        runOnMainSync(()->{activity.menuAction("quit_button");});check(menu.screen.equals("hiscore"),"The final-life result must exit to the high-score screen");check(Arrays.asList(menu.scoreNames[0]).contains("QA Alice"),"A qualifying career total must be submitted under the current player name");capture("phone-career-highscores");
        runOnMainSync(()->{activity.menuAction("menubutton");activity.menuAction("career_button");});check(menu.gameOver,"A saved zero-life run must offer a new game rather than silently continue");
        runOnMainSync(()->{menu.selected=3;activity.menuAction("newgame_button");});check(alice.getInt("lives",0)==3&&alice.getInt("totalScore",-1)==0&&menu.screen.equals("startlevel"),"A new game resets run lives and score while keeping unlocked shifts");check(menu.experts[1],"Starting a new run must keep previously earned expert stars");check(alice.getInt("totalStars",0)==3&&((GameEngine)field("game")).totalStars==3,"A new run must reset earned star capacity without inheriting the previous run's extra slots");
        runOnMainSync(()->{choose(9);});check(bob.getInt("lives",3)==3&&bob.getInt("totalScore",0)==0,"Other players must not inherit a failed run or its reset");
        Method submit=MainActivity.class.getDeclaredMethod("submitScore",int.class,int.class);submit.setAccessible(true);
        runOnMainSync(()->{try{submit.invoke(activity,2,2200);menu.hiscoreMode=2;menu.show("hiscore");}catch(Exception e){throw new RuntimeException(e);}});check(menu.scoreValues[2][0]==2200&&menu.scoreNames[2][0].equals("QA Bob")&&menu.scoreValues[1][0]==2000,"Endless difficulty leaderboards must remain separate");capture("phone-endless-medium-highscores");
        runOnMainSync(()->{menu.underlay="title_screen";menu.show("options");activity.menuAction("music_off");});check(!menu.music&&!settings.getBoolean("music",true),"Selecting OFF must change and persist the global music setting");capture("phone-options-off");runOnMainSync(()->{activity.menuAction("music_on");});check(menu.music&&settings.getBoolean("music",false),"Selecting ON must restore and persist music independently of player progress");
        AssetStore a=new AssetStore(c);for(String name:new String[]{"opt_on","opt_off"}){Bitmap b=a.bitmap("gfx.screens",name,true);int white=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++){int pixel=b.getPixel(x,y);if(Color.alpha(pixel)>0&&(pixel&0xffffff)==0xffffff)white++;}check(white>0,"Original alpha must preserve the white "+name+" lettering");}
        }
        regressions(regression);
        result.putString("summary","PASS: "+checks+" installed save/menu checks; synthetic fixtures; original saves restored");
    }catch(Throwable error){result.putString("failure",error.toString());}finally{if(activity!=null)runOnMainSync(()->{activity.finish();});for(int i=0;i<backups.size();i++)restore(stores.get(i),backups.get(i));}finish(result.containsKey("failure")?0:-1,result);}
}
